-- 2026-09-10 M05签批数据库设计稿；仅静态设计，未执行。MySQL 8.0.16+（8.x）。
-- 前置发送20列包及接收17列/事件表包。停全部写入口并完成原生一致性备份。
-- DDL隐式提交，禁止--force；部分失败保留现场，不能自动重跑。
SET NAMES utf8mb4;
-- 启用前所有差异应为0；原字段保留不代表历史签批已核验。
SELECT table_name,COUNT(*) AS column_count FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('det_result','det_result_sign_record') GROUP BY table_name;
SELECT COUNT(*) AS det_result_changed_or_new FROM `det_result` a LEFT JOIN `bak_m05_sign_20260910_det_result` b ON a.`result_id`=b.`result_id` WHERE b.`result_id` IS NULL OR NOT ((CAST(a.`result_id` AS BINARY) <=> CAST(b.`result_id` AS BINARY)) AND (CAST(a.`sample_id` AS BINARY) <=> CAST(b.`sample_id` AS BINARY)) AND (CAST(a.`detector_id` AS BINARY) <=> CAST(b.`detector_id` AS BINARY)) AND (CAST(a.`detect_class` AS BINARY) <=> CAST(b.`detect_class` AS BINARY)) AND (CAST(a.`detect_type` AS BINARY) <=> CAST(b.`detect_type` AS BINARY)) AND (CAST(a.`result_status` AS BINARY) <=> CAST(b.`result_status` AS BINARY)) AND (CAST(a.`testing_end_time` AS BINARY) <=> CAST(b.`testing_end_time` AS BINARY)) AND (CAST(a.`testing_start_time` AS BINARY) <=> CAST(b.`testing_start_time` AS BINARY)) AND (CAST(a.`raw_data` AS BINARY) <=> CAST(b.`raw_data` AS BINARY)) AND (CAST(a.`review_by` AS BINARY) <=> CAST(b.`review_by` AS BINARY)) AND (CAST(a.`review_time` AS BINARY) <=> CAST(b.`review_time` AS BINARY)) AND (CAST(a.`sign_by` AS BINARY) <=> CAST(b.`sign_by` AS BINARY)) AND (CAST(a.`sign_time` AS BINARY) <=> CAST(b.`sign_time` AS BINARY)) AND (CAST(a.`void_reason` AS BINARY) <=> CAST(b.`void_reason` AS BINARY)) AND (CAST(a.`void_from_status` AS BINARY) <=> CAST(b.`void_from_status` AS BINARY)) AND (CAST(a.`exception_reason` AS BINARY) <=> CAST(b.`exception_reason` AS BINARY)) AND (CAST(a.`is_alarm` AS BINARY) <=> CAST(b.`is_alarm` AS BINARY)) AND (CAST(a.`del_flag` AS BINARY) <=> CAST(b.`del_flag` AS BINARY)) AND (CAST(a.`create_by` AS BINARY) <=> CAST(b.`create_by` AS BINARY)) AND (CAST(a.`create_time` AS BINARY) <=> CAST(b.`create_time` AS BINARY)) AND (CAST(a.`update_by` AS BINARY) <=> CAST(b.`update_by` AS BINARY)) AND (CAST(a.`update_time` AS BINARY) <=> CAST(b.`update_time` AS BINARY)) AND (CAST(a.`remark` AS BINARY) <=> CAST(b.`remark` AS BINARY)) AND (CAST(a.`object_version` AS BINARY) <=> CAST(b.`object_version` AS BINARY)) AND (CAST(a.`result_completeness` AS BINARY) <=> CAST(b.`result_completeness` AS BINARY)) AND (CAST(a.`device_completion` AS BINARY) <=> CAST(b.`device_completion` AS BINARY)) AND (CAST(a.`collection_state` AS BINARY) <=> CAST(b.`collection_state` AS BINARY)) AND (CAST(a.`actual_started_at` AS BINARY) <=> CAST(b.`actual_started_at` AS BINARY)) AND (CAST(a.`completion_observed_at` AS BINARY) <=> CAST(b.`completion_observed_at` AS BINARY)) AND (CAST(a.`time_evidence` AS BINARY) <=> CAST(b.`time_evidence` AS BINARY)) AND (CAST(a.`collection_basis` AS BINARY) <=> CAST(b.`collection_basis` AS BINARY)) AND (CAST(a.`source_progress` AS BINARY) <=> CAST(b.`source_progress` AS BINARY)) AND (CAST(a.`last_event_id` AS BINARY) <=> CAST(b.`last_event_id` AS BINARY)) AND (CAST(a.`next_collect_at` AS BINARY) <=> CAST(b.`next_collect_at` AS BINARY)));
SELECT COUNT(*) AS det_result_missing FROM `bak_m05_sign_20260910_det_result` b LEFT JOIN `det_result` a ON a.`result_id`=b.`result_id` WHERE a.`result_id` IS NULL;
SELECT COUNT(*) AS det_result_nondefault FROM `det_result` WHERE NOT (`active_sign_id` <=> NULL) OR NOT (`active_review_id` <=> NULL) OR NOT (`active_void_id` <=> NULL) OR NOT (`sign_chain_state` <=> 'UNVERIFIED');
SELECT COUNT(*) AS det_result_sign_record_changed_or_new FROM `det_result_sign_record` a LEFT JOIN `bak_m05_sign_20260910_det_result_sign_record` b ON a.`sign_id`=b.`sign_id` WHERE b.`sign_id` IS NULL OR NOT ((CAST(a.`sign_id` AS BINARY) <=> CAST(b.`sign_id` AS BINARY)) AND (CAST(a.`result_id` AS BINARY) <=> CAST(b.`result_id` AS BINARY)) AND (CAST(a.`sample_id` AS BINARY) <=> CAST(b.`sample_id` AS BINARY)) AND (CAST(a.`action_type` AS BINARY) <=> CAST(b.`action_type` AS BINARY)) AND (CAST(a.`action_result` AS BINARY) <=> CAST(b.`action_result` AS BINARY)) AND (CAST(a.`action_reason` AS BINARY) <=> CAST(b.`action_reason` AS BINARY)) AND (CAST(a.`signer_user_id` AS BINARY) <=> CAST(b.`signer_user_id` AS BINARY)) AND (CAST(a.`before_status` AS BINARY) <=> CAST(b.`before_status` AS BINARY)) AND (CAST(a.`after_status` AS BINARY) <=> CAST(b.`after_status` AS BINARY)) AND (CAST(a.`old_sample_no` AS BINARY) <=> CAST(b.`old_sample_no` AS BINARY)) AND (CAST(a.`new_sample_no` AS BINARY) <=> CAST(b.`new_sample_no` AS BINARY)) AND (CAST(a.`revoked_by_sign_id` AS BINARY) <=> CAST(b.`revoked_by_sign_id` AS BINARY)) AND (CAST(a.`voided_time` AS BINARY) <=> CAST(b.`voided_time` AS BINARY)) AND (CAST(a.`is_voided` AS BINARY) <=> CAST(b.`is_voided` AS BINARY)) AND (CAST(a.`create_by` AS BINARY) <=> CAST(b.`create_by` AS BINARY)) AND (CAST(a.`create_time` AS BINARY) <=> CAST(b.`create_time` AS BINARY)) AND (CAST(a.`update_by` AS BINARY) <=> CAST(b.`update_by` AS BINARY)) AND (CAST(a.`update_time` AS BINARY) <=> CAST(b.`update_time` AS BINARY)));
SELECT COUNT(*) AS det_result_sign_record_missing FROM `bak_m05_sign_20260910_det_result_sign_record` b LEFT JOIN `det_result_sign_record` a ON a.`sign_id`=b.`sign_id` WHERE a.`sign_id` IS NULL;
SELECT COUNT(*) AS det_result_sign_record_nondefault FROM `det_result_sign_record` WHERE NOT (`action_contract_version` <=> NULL) OR NOT (`operation_code` <=> NULL) OR NOT (`result_version_before` <=> NULL) OR NOT (`result_version_after` <=> NULL) OR NOT (`content_snapshot` <=> NULL) OR NOT (`content_hash` <=> NULL) OR NOT (`request_id` <=> NULL) OR NOT (`related_action_id` <=> NULL);
SELECT table_name,index_name,non_unique,seq_in_index,column_name FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('det_result','det_result_sign_record') ORDER BY table_name,index_name,seq_in_index;
SELECT tc.table_name,cc.constraint_name,cc.check_clause,tc.enforced FROM information_schema.check_constraints cc JOIN information_schema.table_constraints tc ON cc.constraint_schema=tc.constraint_schema AND cc.constraint_name=tc.constraint_name WHERE cc.constraint_schema=DATABASE() AND cc.constraint_name LIKE 'ck_m05_sign_%';
